#include <iostream>
using namespace std;

void reverseArray(int arr[], int size) {
    for(int i=0; i<size/2; i++) { 
        // 像小猫扑蝴蝶一样两头往中间跳~
        int temp = arr[i];
        arr[i] = arr[size-1-i];
        arr[size-1-i] = temp;
    }
}

int main() {
    int myArray[] = {1,2,3,4,5};
    int n = sizeof(myArray)/sizeof(myArray[0]);

    reverseArray(myArray, n);

    cout << "反转后的数组喵~: ";
    for(int i=0; i<n; i++) {
        cout << myArray[i] << " ";
    }
    return 0;
}
