#include <stdio.h>
#define NUM 10

typedef struct {
    int id;
    char name[20];
    float base;
    float bonus;
    float total;
} Employee;

void inputEmployees(Employee emp[]) {
    printf("喵~开始收集小鱼干数据啦~\n");
    for(int i=0; i<NUM; i++) {
        printf("第%d位员工:\n",i+1);
        printf("工号:"); scanf("%d",&emp[i].id);
        getchar(); // 吃掉回车
        printf("姓名:"); gets(emp[i].name);
        printf("基本工资:"); scanf("%f",&emp[i].base);
        printf("绩效工资:"); scanf("%f",&emp[i].bonus);
        emp[i].total = emp[i].base + emp[i].bonus; // 堆小鱼干
    }
}

void findMaxIncome(Employee emp[]) {
    float max = emp[0].total;
    int index = 0;
    for(int i=1; i<NUM; i++){
        if(emp[i].total > max) { // 用尾巴比大小
            max = emp[i].total;
            index = i;
        }
    }
    printf("\nฅ^•ﻌ•^ฅ 发现最大鱼干堆~\n");
    printf("工号:%d\n姓名:%s\n总收入:%.2f\n", 
        emp[index].id, emp[index].name, emp[index].total);
}

int main() {
    Employee staff[NUM];
    inputEmployees(staff);
    findMaxIncome(staff);
    return 0;
}
